package ae.ad;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

/** Compares analytic gradients with central finite differences. */
public final class GradCheck {
    private static final double H = 1e-6;

    private GradCheck() {}

    /**
     * Max over all input entries of {@code |analytic - numeric| / max(1, |analytic| + |numeric|)}, where numeric
     * is a central difference of a fresh forward pass.
     */
    public static double maxRelError(Function<List<Node>, Node> f, Mat... inputs) {
        List<Node> params = new ArrayList<>();
        for (Mat m : inputs) {
            params.add(Node.param(m));
        }
        f.apply(params).backward();
        double worst = 0;
        for (int p = 0; p < inputs.length; p++) {
            Mat grad = params.get(p).grad();
            for (int i = 0; i < inputs[p].rows(); i++) {
                for (int j = 0; j < inputs[p].cols(); j++) {
                    double base = inputs[p].get(i, j);
                    double plus = eval(f, inputs, p, inputs[p].with(i, j, base + H));
                    double minus = eval(f, inputs, p, inputs[p].with(i, j, base - H));
                    double numeric = (plus - minus) / (2 * H);
                    double analytic = grad.get(i, j);
                    double err = Math.abs(analytic - numeric) / Math.max(1, Math.abs(analytic) + Math.abs(numeric));
                    worst = Math.max(worst, err);
                }
            }
        }
        return worst;
    }

    private static double eval(Function<List<Node>, Node> f, Mat[] inputs, int replaced, Mat replacement) {
        List<Node> ps = new ArrayList<>();
        for (int k = 0; k < inputs.length; k++) {
            ps.add(Node.param(k == replaced ? replacement : inputs[k]));
        }
        return f.apply(ps).value().get(0, 0);
    }
}

package ae.ad;

import java.util.Arrays;

/** Immutable row-major matrix of doubles; rows and cols are both at least 1. */
public final class Mat {
    private final int rows;
    private final int cols;
    private final double[] data;

    private Mat(int rows, int cols, double[] data) {
        this.rows = rows;
        this.cols = cols;
        this.data = data;
    }

    /** Creates a matrix from row-major values; the count must equal rows*cols. */
    public static Mat of(int rows, int cols, double... values) {
        checkDims(rows, cols);
        if (values.length != rows * cols) {
            throw new IllegalArgumentException(
                    "expected " + rows * cols + " values for " + rows + "x" + cols + " but got " + values.length);
        }
        return new Mat(rows, cols, values.clone());
    }

    public static Mat zeros(int rows, int cols) {
        checkDims(rows, cols);
        return new Mat(rows, cols, new double[rows * cols]);
    }

    private static void checkDims(int rows, int cols) {
        if (rows < 1 || cols < 1) {
            throw new IllegalArgumentException("dimensions must be positive: " + rows + "x" + cols);
        }
    }

    public int rows() {
        return rows;
    }

    public int cols() {
        return cols;
    }

    /** Shape as {@code "RxC"}. */
    public String shape() {
        return rows + "x" + cols;
    }

    public double get(int r, int c) {
        return data[r * cols + c];
    }

    public double[] toArray() {
        return data.clone();
    }

    boolean sameShape(Mat o) {
        return rows == o.rows && cols == o.cols;
    }

    private void requireSame(Mat o, String op) {
        if (!sameShape(o)) {
            throw new IllegalArgumentException(op + ": shape mismatch " + shape() + " vs " + o.shape());
        }
    }

    public Mat plus(Mat o) {
        requireSame(o, "plus");
        double[] r = new double[data.length];
        for (int i = 0; i < r.length; i++) {
            r[i] = data[i] + o.data[i];
        }
        return new Mat(rows, cols, r);
    }

    /** Elementwise product. */
    public Mat times(Mat o) {
        requireSame(o, "times");
        double[] r = new double[data.length];
        for (int i = 0; i < r.length; i++) {
            r[i] = data[i] * o.data[i];
        }
        return new Mat(rows, cols, r);
    }

    public Mat scaled(double k) {
        return map(v -> v * k);
    }

    Mat map(java.util.function.DoubleUnaryOperator f) {
        double[] r = new double[data.length];
        for (int i = 0; i < r.length; i++) {
            r[i] = f.applyAsDouble(data[i]);
        }
        return new Mat(rows, cols, r);
    }

    /** Elementwise combination of two same-shaped matrices. */
    Mat zip(Mat o, java.util.function.DoubleBinaryOperator f) {
        requireSame(o, "zip");
        double[] r = new double[data.length];
        for (int i = 0; i < r.length; i++) {
            r[i] = f.applyAsDouble(data[i], o.data[i]);
        }
        return new Mat(rows, cols, r);
    }

    public Mat matmul(Mat o) {
        if (cols != o.rows) {
            throw new IllegalArgumentException("matmul: shape mismatch " + shape() + " vs " + o.shape());
        }
        double[] r = new double[rows * o.cols];
        for (int i = 0; i < rows; i++) {
            for (int k = 0; k < cols; k++) {
                double a = data[i * cols + k];
                for (int j = 0; j < o.cols; j++) {
                    r[i * o.cols + j] += a * o.data[k * o.cols + j];
                }
            }
        }
        return new Mat(rows, o.cols, r);
    }

    public Mat transpose() {
        double[] r = new double[data.length];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                r[j * rows + i] = data[i * cols + j];
            }
        }
        return new Mat(cols, rows, r);
    }

    /** Sum of each column as a 1 x cols matrix. */
    Mat columnSums() {
        double[] r = new double[cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                r[j] += data[i * cols + j];
            }
        }
        return new Mat(1, cols, r);
    }

    double sumAll() {
        double s = 0;
        for (double v : data) {
            s += v;
        }
        return s;
    }

    Mat filled(double v) {
        double[] r = new double[data.length];
        Arrays.fill(r, v);
        return new Mat(rows, cols, r);
    }

    /** True when shapes match and every entry differs by at most {@code eps}. */
    public boolean approx(Mat o, double eps) {
        if (!sameShape(o)) {
            return false;
        }
        for (int i = 0; i < data.length; i++) {
            if (!(Math.abs(data[i] - o.data[i]) <= eps)) { // NaN never matches
                return false;
            }
        }
        return true;
    }

    /** Copy with one entry replaced. */
    Mat with(int r, int c, double v) {
        double[] d = data.clone();
        d[r * cols + c] = v;
        return new Mat(rows, cols, d);
    }

    @Override
    public String toString() {
        return shape() + Arrays.toString(data);
    }
}

package ae.ad;

import java.util.ArrayList;
import java.util.List;
import java.util.SplittableRandom;

/** Fully connected network: tanh between layers, linear output; deterministic for a seed. */
public final class Mlp {
    private final List<Node> params = new ArrayList<>();

    /** {@code sizes} = input width, hidden widths..., output width (at least two, all positive). */
    public Mlp(long seed, int... sizes) {
        if (sizes.length < 2) {
            throw new IllegalArgumentException("need at least input and output sizes");
        }
        SplittableRandom rnd = new SplittableRandom(seed);
        for (int l = 0; l + 1 < sizes.length; l++) {
            int in = sizes[l];
            int out = sizes[l + 1];
            if (in < 1 || out < 1) {
                throw new IllegalArgumentException("layer sizes must be positive");
            }
            double bound = Math.sqrt(6.0 / (in + out));
            double[] w = new double[in * out];
            for (int i = 0; i < w.length; i++) {
                w[i] = (rnd.nextDouble() * 2 - 1) * bound;
            }
            params.add(Node.param(Mat.of(in, out, w)));
            params.add(Node.param(Mat.zeros(1, out)));
        }
    }

    /** Current parameters in order W0, b0, W1, b1, ...; {@link #sgd} replaces them, so re-fetch after a step. */
    public List<Node> params() {
        return List.copyOf(params);
    }

    public Node forward(Node x) {
        Node h = x;
        int layers = params.size() / 2;
        for (int l = 0; l < layers; l++) {
            h = Node.add(Node.matmul(h, params.get(2 * l)), params.get(2 * l + 1));
            if (l + 1 < layers) {
                h = Node.tanh(h);
            }
        }
        return h;
    }

    /** value -= lr * grad for every parameter, then clears the grads. */
    public void sgd(double lr) {
        List<Node> next = new ArrayList<>();
        for (Node p : params) {
            next.add(Node.param(p.value().plus(p.grad().scaled(-lr))));
        }
        params.clear();
        params.addAll(next);
    }
}

package ae.ad;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.function.Consumer;

/**
 * A value in a computation graph. Build graphs with the static ops, call {@link #backward()} on a 1x1 result,
 * then read {@link #grad()} of the parameters. Leaves ({@link #param}) accumulate gradient across backward calls
 * until {@link #zeroGrad(Collection)}; intermediate nodes are reset on every backward pass.
 */
public final class Node {
    private final Mat value;
    private Mat grad;
    private final List<Node> parents;
    /** Propagates this node's grad into its parents; null for leaves. */
    private final Consumer<Mat> backwardFn;
    private final boolean requiresGrad;

    private Node(Mat value, List<Node> parents, Consumer<Mat> backwardFn, boolean requiresGrad) {
        this.value = value;
        this.grad = Mat.zeros(value.rows(), value.cols());
        this.parents = parents;
        this.backwardFn = backwardFn;
        this.requiresGrad = requiresGrad;
    }

    public static Node param(Mat value) {
        return new Node(value, List.of(), null, true);
    }

    public static Node constant(Mat value) {
        return new Node(value, List.of(), null, false);
    }

    public Mat value() {
        return value;
    }

    public Mat grad() {
        return grad;
    }

    private static Node derived(Mat value, List<Node> parents, Consumer<Mat> backwardFn) {
        boolean req = parents.stream().anyMatch(p -> p.requiresGrad);
        return new Node(value, parents, req ? backwardFn : null, req);
    }

    private void accumulate(Mat g) {
        if (requiresGrad) {
            grad = grad.plus(g);
        }
    }

    /** Zeroes the grads of the given nodes. */
    public static void zeroGrad(Collection<Node> nodes) {
        for (Node n : nodes) {
            n.grad = Mat.zeros(n.value.rows(), n.value.cols());
        }
    }

    // ---- ops ----

    /** Same-shape sum, or {@code b} a 1 x cols row broadcast over the rows of {@code a}. */
    public static Node add(Node a, Node b) {
        Mat av = a.value;
        Mat bv = b.value;
        if (av.sameShape(bv)) {
            return derived(av.plus(bv), List.of(a, b), g -> {
                a.accumulate(g);
                b.accumulate(g);
            });
        }
        if (bv.rows() == 1 && bv.cols() == av.cols()) {
            double[] out = new double[av.rows() * av.cols()];
            for (int i = 0; i < av.rows(); i++) {
                for (int j = 0; j < av.cols(); j++) {
                    out[i * av.cols() + j] = av.get(i, j) + bv.get(0, j);
                }
            }
            return derived(Mat.of(av.rows(), av.cols(), out), List.of(a, b), g -> {
                a.accumulate(g);
                b.accumulate(g.columnSums());
            });
        }
        throw new IllegalArgumentException("add: shape mismatch " + av.shape() + " vs " + bv.shape());
    }

    public static Node sub(Node a, Node b) {
        Mat v = a.value.zip(b.value, (x, y) -> x - y);
        return derived(v, List.of(a, b), g -> {
            a.accumulate(g);
            b.accumulate(g.scaled(-1));
        });
    }

    /** Elementwise product. */
    public static Node mul(Node a, Node b) {
        Mat av = a.value;
        Mat bv = b.value;
        return derived(av.times(bv), List.of(a, b), g -> {
            a.accumulate(g.times(bv));
            b.accumulate(g.times(av));
        });
    }

    public static Node matmul(Node a, Node b) {
        Mat av = a.value;
        Mat bv = b.value;
        return derived(av.matmul(bv), List.of(a, b), g -> {
            a.accumulate(g.matmul(bv.transpose()));
            b.accumulate(av.transpose().matmul(g));
        });
    }

    public static Node scale(Node a, double k) {
        return derived(a.value.scaled(k), List.of(a), g -> a.accumulate(g.scaled(k)));
    }

    public static Node tanh(Node a) {
        Mat y = a.value.map(Math::tanh);
        return derived(y, List.of(a), g -> a.accumulate(g.zip(y, (gi, yi) -> gi * (1 - yi * yi))));
    }

    public static Node relu(Node a) {
        Mat x = a.value;
        return derived(x.map(v -> v > 0 ? v : 0), List.of(a), g -> a.accumulate(g.zip(x, (gi, xi) -> xi > 0 ? gi : 0)));
    }

    public static Node sigmoid(Node a) {
        Mat y = a.value.map(Node::sigmoidOf);
        return derived(y, List.of(a), g -> a.accumulate(g.zip(y, (gi, yi) -> gi * yi * (1 - yi))));
    }

    private static double sigmoidOf(double v) {
        if (v >= 0) {
            return 1 / (1 + Math.exp(-v));
        }
        double e = Math.exp(v);
        return e / (1 + e);
    }

    public static Node square(Node a) {
        Mat x = a.value;
        return derived(x.times(x), List.of(a), g -> a.accumulate(g.times(x).scaled(2)));
    }

    /** Sum of all entries as a 1x1 node. */
    public static Node sum(Node a) {
        Mat x = a.value;
        return derived(Mat.of(1, 1, x.sumAll()), List.of(a), g -> a.accumulate(x.filled(g.get(0, 0))));
    }

    /** Mean of all entries as a 1x1 node. */
    public static Node mean(Node a) {
        Mat x = a.value;
        int n = x.rows() * x.cols();
        return derived(Mat.of(1, 1, x.sumAll() / n), List.of(a), g -> a.accumulate(x.filled(g.get(0, 0) / n)));
    }

    // ---- backward ----

    /**
     * Back-propagates from this 1x1 node. Ancestors are visited once each in reverse topological order
     * (iteratively). Intermediate grads are reset first; leaf grads accumulate.
     */
    public void backward() {
        if (value.rows() != 1 || value.cols() != 1) {
            throw new IllegalStateException("backward needs a 1x1 node but this is " + value.shape());
        }
        List<Node> order = topoOrder();
        for (Node n : order) {
            if (!n.parents.isEmpty()) {
                zeroGrad(List.of(n));
            }
        }
        if (!requiresGrad) {
            return;
        }
        grad = grad.plus(Mat.of(1, 1, 1));
        for (int i = order.size() - 1; i >= 0; i--) {
            Node n = order.get(i);
            if (n.backwardFn != null) {
                n.backwardFn.accept(n.grad);
            }
        }
    }

    /** Parents-before-children order of this node and its ancestors, via an explicit stack. */
    private List<Node> topoOrder() {
        List<Node> order = new ArrayList<>();
        IdentityHashMap<Node, Boolean> seen = new IdentityHashMap<>();
        ArrayDeque<Node> stack = new ArrayDeque<>();
        ArrayDeque<Integer> next = new ArrayDeque<>();
        stack.push(this);
        next.push(0);
        seen.put(this, Boolean.TRUE);
        while (!stack.isEmpty()) {
            Node n = stack.peek();
            int idx = next.pop();
            if (idx < n.parents.size()) {
                next.push(idx + 1);
                Node p = n.parents.get(idx);
                if (seen.put(p, Boolean.TRUE) == null) {
                    stack.push(p);
                    next.push(0);
                }
            } else {
                stack.pop();
                order.add(n);
            }
        }
        return order;
    }
}

