package ae.ad;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import java.util.SplittableRandom;
import java.util.function.Function;
import org.junit.jupiter.api.Test;

class GradCheckTest {
    private static Mat random(SplittableRandom r, int rows, int cols) {
        double[] v = new double[rows * cols];
        for (int i = 0; i < v.length; i++) {
            v[i] = r.nextDouble() * 2 - 1 + 0.05; // avoid exact 0 (relu kink)
        }
        return Mat.of(rows, cols, v);
    }

    private static void check(Function<List<Node>, Node> f, Mat... inputs) {
        double err = GradCheck.maxRelError(f, inputs);
        assertTrue(err < 1e-6, "max relative error " + err);
    }

    @Test
    void everyUnaryOpPassesTheCheck() {
        SplittableRandom r = new SplittableRandom(1);
        Mat x = random(r, 3, 4);
        check(in -> Node.sum(Node.tanh(in.get(0))), x);
        check(in -> Node.sum(Node.relu(in.get(0))), x);
        check(in -> Node.sum(Node.sigmoid(in.get(0))), x);
        check(in -> Node.sum(Node.square(in.get(0))), x);
        check(in -> Node.mean(Node.scale(in.get(0), -2.5)), x);
    }

    @Test
    void everyBinaryOpPassesTheCheck() {
        SplittableRandom r = new SplittableRandom(2);
        Mat a = random(r, 3, 4);
        Mat b = random(r, 3, 4);
        Mat row = random(r, 1, 4);
        Mat w = random(r, 4, 2);
        check(in -> Node.sum(Node.add(in.get(0), in.get(1))), a, b);
        check(in -> Node.sum(Node.square(Node.add(in.get(0), in.get(1)))), a, row);
        check(in -> Node.sum(Node.square(Node.sub(in.get(0), in.get(1)))), a, b);
        check(in -> Node.sum(Node.mul(in.get(0), in.get(1))), a, b);
        check(in -> Node.sum(Node.square(Node.matmul(in.get(0), in.get(1)))), a, w);
    }

    @Test
    void composedGraphWithSharingPassesTheCheck() {
        SplittableRandom r = new SplittableRandom(3);
        Mat x = random(r, 2, 3);
        Mat w = random(r, 3, 3);
        Mat b = random(r, 1, 3);
        check(in -> {
            Node h = Node.tanh(Node.add(Node.matmul(in.get(0), in.get(1)), in.get(2)));
            Node g = Node.sigmoid(Node.matmul(h, in.get(1))); // w reused
            return Node.mean(Node.mul(g, h));
        }, x, w, b);
    }

    @Test
    void checkerCanFailAtAKink() {
        // relu at exactly 0: analytic subgradient 0, central difference 0.5 -> error ~0.5
        double err = GradCheck.maxRelError(in -> Node.sum(Node.relu(in.get(0))), Mat.of(1, 1, 0));
        assertEquals(0.5, err, 1e-3);
    }

    @Test
    void checkerDetectsAWrongGradient() {
        // f(x) = sum(x*x) computed through a graph that treats one factor as a constant: grad is x, truth is 2x
        double err = GradCheck.maxRelError(in -> {
            Node x = in.get(0);
            Node frozen = Node.constant(x.value());
            return Node.sum(Node.mul(x, frozen));
        }, Mat.of(1, 2, 3, 4));
        assertTrue(err > 0.1, "err " + err);
    }
}

package ae.ad;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class MlpTest {
    private static final Mat XOR_X = Mat.of(4, 2, 0, 0, 0, 1, 1, 0, 1, 1);
    private static final Mat XOR_Y = Mat.of(4, 1, 0, 1, 1, 0);

    private static Node loss(Mlp m) {
        Node out = m.forward(Node.constant(XOR_X));
        return Node.mean(Node.square(Node.sub(out, Node.constant(XOR_Y))));
    }

    @Test
    void paramShapesFollowLayerSizes() {
        Mlp m = new Mlp(7, 2, 3, 1);
        List<Node> p = m.params();
        assertEquals(4, p.size());
        assertEquals("2x3", p.get(0).value().shape());
        assertEquals("1x3", p.get(1).value().shape());
        assertEquals("3x1", p.get(2).value().shape());
        assertEquals("1x1", p.get(3).value().shape());
        assertTrue(p.get(1).value().approx(Mat.zeros(1, 3), 0), "biases start at zero");
        double bound = Math.sqrt(6.0 / 5); // layer 0: in 2, out 3
        for (double v : p.get(0).value().toArray()) {
            assertTrue(Math.abs(v) <= bound, "weight " + v + " outside +-" + bound);
        }
    }

    @Test
    void sameSeedSameWeightsDifferentSeedDiffers() {
        Mlp a = new Mlp(5, 2, 4, 1);
        Mlp b = new Mlp(5, 2, 4, 1);
        Mlp c = new Mlp(6, 2, 4, 1);
        assertTrue(a.params().get(0).value().approx(b.params().get(0).value(), 0));
        assertFalse(a.params().get(0).value().approx(c.params().get(0).value(), 1e-12));
    }

    @Test
    void rejectsTooFewSizes() {
        assertThrows(IllegalArgumentException.class, () -> new Mlp(1, 3));
        assertThrows(IllegalArgumentException.class, () -> new Mlp(1, 3, 0, 1));
    }

    @Test
    void gradientCheckOnTheWholeNetwork() {
        Mlp m = new Mlp(11, 2, 3, 1);
        List<Node> ps = m.params();
        Mat[] inputs = ps.stream().map(Node::value).toArray(Mat[]::new);
        double err = GradCheck.maxRelError(in -> {
            // rebuild the same network on the supplied params: forward = tanh(x W0 + b0) W1 + b1
            Node h = Node.tanh(Node.add(Node.matmul(Node.constant(XOR_X), in.get(0)), in.get(1)));
            Node out = Node.add(Node.matmul(h, in.get(2)), in.get(3));
            return Node.mean(Node.square(Node.sub(out, Node.constant(XOR_Y))));
        }, inputs);
        assertTrue(err < 1e-6, "err " + err);
        // and the Mlp's own forward agrees with that hand-built network
        Node viaMlp = m.forward(Node.constant(XOR_X));
        Node h = Node.tanh(Node.add(Node.matmul(Node.constant(XOR_X), ps.get(0)), ps.get(1)));
        Node byHand = Node.add(Node.matmul(h, ps.get(2)), ps.get(3));
        assertTrue(viaMlp.value().approx(byHand.value(), 1e-12));
    }

    @Test
    void sgdMovesAgainstTheGradientAndClearsGrads() {
        Mlp m = new Mlp(3, 2, 3, 1);
        Node l = loss(m);
        l.backward();
        Mat w0 = m.params().get(0).value();
        Mat g0 = m.params().get(0).grad();
        m.sgd(0.1);
        Mat expected = w0.plus(g0.scaled(-0.1));
        assertTrue(expected.approx(m.params().get(0).value(), 1e-12));
        assertTrue(Mat.zeros(2, 3).approx(m.params().get(0).grad(), 0), "grads cleared after step");
    }

    @Test
    void trainsXorBelowThreshold() {
        Mlp m = new Mlp(42, 2, 4, 1);
        double first = loss(m).value().get(0, 0);
        double last = first;
        for (int epoch = 0; epoch < 3000; epoch++) {
            Node l = loss(m);
            l.backward();
            m.sgd(0.3);
            last = l.value().get(0, 0);
        }
        assertTrue(last < 0.01, "final loss " + last + " (initial " + first + ")");
        Mat out = m.forward(Node.constant(XOR_X)).value();
        double[] y = out.toArray();
        assertTrue(y[0] < 0.2 && y[1] > 0.8 && y[2] > 0.8 && y[3] < 0.2, java.util.Arrays.toString(y));
    }

    @Test
    void trainingIsDeterministicForASeed() {
        double[] a = train(9);
        double[] b = train(9);
        assertArrayEquals(a, b, 0);
    }

    private static double[] train(long seed) {
        Mlp m = new Mlp(seed, 2, 3, 1);
        for (int i = 0; i < 50; i++) {
            loss(m).backward();
            m.sgd(0.1);
        }
        return m.forward(Node.constant(XOR_X)).value().toArray();
    }
}

package ae.ad;

import static org.junit.jupiter.api.Assertions.*;

import java.util.List;
import org.junit.jupiter.api.Test;

class NodeTest {
    private static final double EPS = 1e-9;

    private static void assertMat(Mat expected, Mat actual) {
        assertTrue(expected.approx(actual, EPS), "expected " + expected + " but was " + actual);
    }

    @Test
    void addWithRowBroadcastHasLiteralGradients() {
        Node a = Node.param(Mat.of(2, 2, 1, 2, 3, 4));
        Node b = Node.param(Mat.of(1, 2, 10, 20));
        Node s = Node.sum(Node.add(a, b));
        assertMat(Mat.of(2, 2, 11, 22, 13, 24), Node.add(a, b).value());
        s.backward();
        assertMat(Mat.of(2, 2, 1, 1, 1, 1), a.grad());
        assertMat(Mat.of(1, 2, 2, 2), b.grad()); // bias grad = sum over the 2 rows
    }

    @Test
    void mulGradientsSwapOperands() {
        Node a = Node.param(Mat.of(1, 2, 1, 2));
        Node b = Node.param(Mat.of(1, 2, 3, 4));
        Node.sum(Node.mul(a, b)).backward();
        assertMat(Mat.of(1, 2, 3, 4), a.grad());
        assertMat(Mat.of(1, 2, 1, 2), b.grad());
    }

    @Test
    void subGradientsHaveOppositeSigns() {
        Node a = Node.param(Mat.of(1, 2, 5, 6));
        Node b = Node.param(Mat.of(1, 2, 1, 1));
        Node.sum(Node.sub(a, b)).backward();
        assertMat(Mat.of(1, 2, 1, 1), a.grad());
        assertMat(Mat.of(1, 2, -1, -1), b.grad());
    }

    @Test
    void matmulLiteralValueAndGradients() {
        Node a = Node.param(Mat.of(2, 2, 1, 2, 3, 4));
        Node b = Node.param(Mat.of(2, 2, 5, 6, 7, 8));
        Node p = Node.matmul(a, b);
        assertMat(Mat.of(2, 2, 19, 22, 43, 50), p.value());
        Node.sum(p).backward();
        // dA[i][k] = row sum k of B = [11, 15]; dB[k][j] = column sum k of A = [4, 6]
        assertMat(Mat.of(2, 2, 11, 15, 11, 15), a.grad());
        assertMat(Mat.of(2, 2, 4, 4, 6, 6), b.grad());
    }

    @Test
    void matmulNonSquareShapes() {
        Node a = Node.param(Mat.of(1, 3, 1, 2, 3));
        Node b = Node.param(Mat.of(3, 2, 1, 0, 0, 1, 1, 1));
        Node p = Node.matmul(a, b);
        assertMat(Mat.of(1, 2, 4, 5), p.value());
        Node.sum(p).backward();
        assertMat(Mat.of(1, 3, 1, 1, 2), a.grad());
        assertMat(Mat.of(3, 2, 1, 1, 2, 2, 3, 3), b.grad());
    }

    @Test
    void tanhAtHalfHasLiteralGradient() {
        Node x = Node.param(Mat.of(1, 1, 0.5));
        Node y = Node.tanh(x);
        assertEquals(0.46211715726, y.value().get(0, 0), 1e-9);
        y.backward();
        assertEquals(0.78644773296, x.grad().get(0, 0), 1e-9); // 1 - tanh(0.5)^2
    }

    @Test
    void reluPassesOnlyPositiveAndIsZeroAtZero() {
        Node x = Node.param(Mat.of(1, 3, -1, 0, 2));
        Node.sum(Node.relu(x)).backward();
        assertMat(Mat.of(1, 3, 0, 0, 1), x.grad());
    }

    @Test
    void sigmoidAtZero() {
        Node x = Node.param(Mat.of(1, 1, 0));
        Node y = Node.sigmoid(x);
        assertEquals(0.5, y.value().get(0, 0), EPS);
        y.backward();
        assertEquals(0.25, x.grad().get(0, 0), EPS);
    }

    @Test
    void sigmoidIsStableForLargeMagnitudes() {
        Node x = Node.param(Mat.of(1, 2, -800, 800));
        Node y = Node.sigmoid(x);
        assertMat(Mat.of(1, 2, 0, 1), y.value());
        Node.sum(y).backward();
        assertMat(Mat.of(1, 2, 0, 0), x.grad());
    }

    @Test
    void squareScaleMeanSum() {
        Node x = Node.param(Mat.of(1, 2, 3, -2));
        Node.sum(Node.square(x)).backward();
        assertMat(Mat.of(1, 2, 6, -4), x.grad());

        Node y = Node.param(Mat.of(2, 2, 1, 2, 3, 4));
        Node m = Node.mean(y);
        assertEquals(2.5, m.value().get(0, 0), EPS);
        m.backward();
        assertMat(Mat.of(2, 2, 0.25, 0.25, 0.25, 0.25), y.grad());

        Node z = Node.param(Mat.of(1, 2, 1, 1));
        Node.sum(Node.scale(z, 3)).backward();
        assertMat(Mat.of(1, 2, 3, 3), z.grad());
    }

    @Test
    void sharedNodeAccumulatesBothContributions() {
        Node x = Node.param(Mat.of(1, 3, 1, 2, 3));
        Node.sum(Node.mul(x, x)).backward();
        assertMat(Mat.of(1, 3, 2, 4, 6), x.grad());

        Node y = Node.param(Mat.of(1, 1, 5));
        Node.sum(Node.add(y, y)).backward();
        assertMat(Mat.of(1, 1, 2), y.grad());
    }

    @Test
    void diamondGraphVisitsSharedIntermediateOnce() {
        // t = x*x; f = t + t*t  => df/dx = 2x + 4x^3 ; at x = 2: 4 + 32 = 36
        Node x = Node.param(Mat.of(1, 1, 2));
        Node t = Node.mul(x, x);
        Node f = Node.add(t, Node.mul(t, t));
        assertEquals(20, f.value().get(0, 0), EPS);
        f.backward();
        assertEquals(36, x.grad().get(0, 0), EPS);
    }

    @Test
    void secondBackwardAccumulatesUntilZeroGrad() {
        Node x = Node.param(Mat.of(1, 1, 3));
        Node f = Node.square(x);
        f.backward();
        assertEquals(6, x.grad().get(0, 0), EPS);
        f.backward();
        assertEquals(12, x.grad().get(0, 0), EPS);
        Node.zeroGrad(List.of(x, f));
        assertEquals(0, x.grad().get(0, 0), EPS);
        f.backward();
        assertEquals(6, x.grad().get(0, 0), EPS);
    }

    @Test
    void constantsNeverReceiveGradient() {
        Node c = Node.constant(Mat.of(1, 2, 7, 8));
        Node x = Node.param(Mat.of(1, 2, 1, 1));
        Node.sum(Node.mul(c, x)).backward();
        assertMat(Mat.of(1, 2, 7, 8), x.grad());
        assertMat(Mat.zeros(1, 2), c.grad());
    }

    @Test
    void backwardRequiresScalar() {
        Node x = Node.param(Mat.of(1, 2, 1, 2));
        IllegalStateException e = assertThrows(IllegalStateException.class, x::backward);
        assertTrue(e.getMessage().contains("1x2"), e.getMessage());
    }

    @Test
    void deepChainDoesNotOverflowTheStack() {
        Node x = Node.param(Mat.of(1, 1, 1));
        Node one = Node.constant(Mat.of(1, 1, 1));
        Node n = x;
        for (int i = 0; i < 200_000; i++) {
            n = Node.add(n, one);
        }
        assertEquals(200_001, n.value().get(0, 0), EPS);
        n.backward();
        assertEquals(1, x.grad().get(0, 0), EPS);
    }

    @Test
    void shapeErrorsNameBothShapes() {
        Node a = Node.param(Mat.of(2, 3, 1, 2, 3, 4, 5, 6));
        Node b = Node.param(Mat.of(2, 3, 1, 2, 3, 4, 5, 6));
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> Node.matmul(a, b));
        assertTrue(e.getMessage().contains("2x3") && e.getMessage().indexOf("2x3") != e.getMessage().lastIndexOf("2x3"),
                e.getMessage());
        Node c = Node.param(Mat.of(3, 2, 1, 2, 3, 4, 5, 6));
        IllegalArgumentException e2 = assertThrows(IllegalArgumentException.class, () -> Node.add(a, c));
        assertTrue(e2.getMessage().contains("2x3") && e2.getMessage().contains("3x2"), e2.getMessage());
        // a column vector is not a broadcastable row
        Node col = Node.param(Mat.of(2, 1, 1, 2));
        assertThrows(IllegalArgumentException.class, () -> Node.add(a, col));
    }

    @Test
    void matRejectsBadConstruction() {
        assertThrows(IllegalArgumentException.class, () -> Mat.of(2, 2, 1, 2, 3));
        assertThrows(IllegalArgumentException.class, () -> Mat.zeros(0, 3));
    }
}
